def solve(rows):
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 3 != 0 or i == len(rows) - 1:
            filtered_rows.append(row)

    if not filtered_rows:
        return []

    rotated_rows = filtered_rows[2:] + filtered_rows[:2]

    group_map = {}
    for row in rotated_rows:
        group, score, timestamp, name = row
        if group not in group_map:
            group_map[group] = []
        group_map[group].append((score, timestamp, name))

    result = []
    for group in sorted(group_map.keys()):
        best_row = None
        best_score = float('-inf')
        best_timestamp = float('inf')
        best_name = ''

        for score, timestamp, name in group_map[group]:
            if score > best_score:
                best_score = score
                best_timestamp = timestamp
                best_name = name
            elif score == best_score:
                if timestamp < best_timestamp:
                    best_timestamp = timestamp
                    best_name = name
                elif timestamp == best_timestamp:
                    if name > best_name:
                        best_name = name

        result.append([group, best_name])

    return result

